const int BARREL_ITER = 40;
const float BARREL_AMP = 0.05;
const vec4 COLOR_LIFT = vec4(0.0, 0.0, 0.0, 0.04);
const vec4 COLOR_GAMMA = vec4(0.0, 0.0, 0.0, -0.1);
const vec4 COLOR_GAIN = vec4(1.0, 1.01, 1.05, 1.2);

const float PI = acos(-1.0);
const float SQRT2 = sqrt(2.0);
const float INV_SQRT2 = 1.0 / SQRT2;
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

#define saturate(x) clamp(x, 0.0, 1.0)

// http://www.jcgt.org/published/0009/03/02/
uvec3 hash3u(uvec3 v) {
  v = v * 1664525u + 1013904223u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  v ^= v >> 16u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  return v;
}

vec3 hash3f(vec3 v) {
  uvec3 r = floatBitsToUint(v);
  return vec3(hash3u(r)) / float(-1u);
}

uvec3 seed;
vec3 random3() {
  seed = hash3u(seed);
  return vec3(seed) / float(-1u);
}

vec3 grad(float phase) {
  return saturate(
    1.0 - 3.0 * abs(vec3(0.25, 0.5, 0.75) - phase)
  ) * 4.0 / float(BARREL_ITER);
}

vec2 barrelUv(vec2 uv, float amp) {
  const float CORN = 0.5 * SQRT2;

  float a = min(3.0 * sqrt(amp), INV_SQRT2 * PI);
  float zoom = INV_SQRT2 / (tan(INV_SQRT2 * a) + INV_SQRT2);

  vec2 uvt = uv - 0.5;
  return saturate(mix(
    vec2(0.5),
    uv + normalize(uvt) * tan(length(uvt) * a),
    zoom
  ));
}

vec3 RRTAndODTFit(vec3 v) {
  vec3 a = v * (v + 0.0245786) - 0.000090537;
  vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
  return a / b;
}

vec3 tonemapACESHill(vec3 sRGB) {
  vec3 inputCol = mat3(
    0.59719, 0.07600, 0.02840,
    0.35458, 0.90834, 0.13383,
    0.04823, 0.01566, 0.83777
  ) * sRGB;
  vec3 fittedCol = RRTAndODTFit(inputCol);
  vec3 outputCol = mat3(
    1.60475, -0.10208, -0.00327,
    -0.53108, 1.10813, -0.07276,
    -0.07367, -0.00605, 1.07602
  ) * fittedCol;
  return saturate(outputCol);
}

vec3 sRGBOETF(vec3 x) {
  vec3 x_ = saturate(x);
  return mix(
    x_ * 12.92,
    pow(x_, vec3(0.4167)) * 1.055 - 0.055,
    step(0.0031308, x_)
  );
}

vec3 liftGammaGain(vec3 rgb) {
  vec4 liftt = 1.0 - pow(1.0 - COLOR_LIFT, log2(COLOR_GAIN + 1.0));

  vec4 gammat = COLOR_GAMMA.rgba - vec4(0.0, 0.0, 0.0, dot(LUMA, COLOR_GAMMA.rgb));
  vec4 gammatTemp = 1.0 + 4.0 * abs(gammat);
  gammat = mix(gammatTemp, 1.0 / gammatTemp, step(0.0, gammat));

  vec3 col = rgb;
  float luma = dot(LUMA, col);

  col = pow(col, gammat.rgb);
  col *= pow(COLOR_GAIN.rgb, gammat.rgb);
  col = max(mix(2.0 * liftt.rgb, vec3(1.0), col), 0.0);

  luma = pow(luma, gammat.a);
  luma *= pow(COLOR_GAIN.a, gammat.a);
  luma = max(mix(2.0 * liftt.a, 1.0, luma), 0.0);

  col += luma - dot(LUMA, col);

  return saturate(col);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  seed = uvec3(fragCoord, iFrame);

  vec2 uv = fragCoord.xy / iResolution.xy;
  vec2 p = uv * 2.0 - 1.0;
  p.x *= iResolution.x / iResolution.y;

  vec3 col = vec3(0.0);

  for (int i = 0; i < BARREL_ITER; i ++) {
    float phase = (float(i) + random3().x) / float(BARREL_ITER);
    vec3 tint = grad(phase);
    vec2 uv = barrelUv(uv, BARREL_AMP * phase);
    col += tint * texture(iChannel0, uv).xyz;
  }

  col *= 1.0 - 0.2 * length(p);
  col = tonemapACESHill(max(col, 0.0));
  col = sRGBOETF(col);
  col = liftGammaGain(col);

  fragColor = vec4(col, 1.0);
}

const int TRACE_ITER = 20;
const float EPSILON = 0.01;
const float FAR = 100.0;
const float ROUGHNESS = 0.06;
const float ROUGHNESS_SQ = ROUGHNESS * ROUGHNESS;
const float LIGHT_AMP = 2.0;

const float PI = acos(-1.0);
const float TAU = 2.0 * PI;

// http://www.jcgt.org/published/0009/03/02/
uvec3 hash3u(uvec3 v) {
  v = v * 1664525u + 1013904223u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  v ^= v >> 16u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  return v;
}

vec3 hash3f(vec3 v) {
  uvec3 r = floatBitsToUint(v);
  return vec3(hash3u(r)) / float(-1u);
}

uvec3 seed;
vec3 random3() {
  seed = hash3u(seed);
  return vec3(seed) / float(-1u);
}

mat2 rotate2D(float t) {
  float c = cos(t);
  float s = sin(t);
  return mat2(c, s, -s, c);
}

mat3 orthBas(vec3 z) {
  z = normalize(z);
  vec3 up = abs(z.y) < 0.99 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0);
  vec3 x = normalize(cross(up, z));
  return mat3(x, cross(z, x), z);
}

vec3 rotObject(vec3 p) {
  p.zx *= rotate2D(iTime);
  p.xy *= rotate2D(-1.0);
  p.yz *= rotate2D(-1.0);
  return p;
}

vec3 invRotObject(vec3 p) {
  p.yz *= rotate2D(1.0);
  p.xy *= rotate2D(1.0);
  p.zx *= rotate2D(-iTime);
  return p;
}

float isectPlane(vec3 ro, vec3 rd, vec3 n) {
  float t = -dot(ro, n) / dot(rd, n);
  return t < 0.0 ? FAR : t;
}

vec4 isectBox(vec3 ro, vec3 rd, vec3 s) {
  vec3 xo = -ro / rd;
  vec3 xs = abs(s / rd);

  vec3 dfv = xo - xs;
  vec3 dbv = xo + xs;

  float df = max(dfv.x, max(dfv.y, dfv.z));
  float db = min(dbv.x, min(dbv.y, dbv.z));
  if (df < 0.0) { return vec4(FAR); }
  if (db < df) { return vec4(FAR); }

  vec3 n = -sign(rd) * step(vec3(df), dfv);
  return vec4(n, df);
}

// FAKE rounded box, just modified the normal
vec4 isectRoundedBox(vec3 ro, vec3 rd, vec3 s, float r) {
  vec4 isect = isectBox(ro, rd, s);
  float d = isect.w;

  if (d >= FAR) return vec4(FAR);

  vec3 rp = ro + rd * d;
  vec3 st = s - r;
  vec3 rpt = clamp(rp, -st, st);
  vec3 N = normalize(rp - rpt);

  d += 0.01 * r * length(N - isect.xyz);

  return vec4(N, d);
}

vec4 isectObject(vec3 ro, vec3 rd) {
  vec4 isect = vec4(FAR);

  ro = rotObject(ro);
  rd = rotObject(rd);

  for (int i = 0; i < 12; i++) {
    float fi = float(i);
    int i6 = i % 6;
    float phase = mod(0.5 * iTime - fi, 6.0);

    if (phase < 2.9) {
      vec3 rot = ro;

      float start = 0.3 * smoothstep(1.9, 2.9, phase);
      float end = 0.3 * smoothstep(0.0, 1.0, phase);

      float flip = 2.0 * floor(fi / 6.0) - 1.0;

      rot -= flip * (
        i6 == 0 ? vec3(-0.3) :
        i6 == 1 ? vec3(0.3, -0.3, -0.3) :
        i6 == 2 ? vec3(0.3, 0.3, -0.3) :
        i6 == 3 ? vec3(0.3, 0.3, 0.3) :
        i6 == 4 ? vec3(-0.3, 0.3, 0.3) :
                  vec3(-0.3, 0.3, -0.3)
      );

      vec3 dir = flip * (
        i6 == 0 ? vec3(1.0, 0.0, 0.0) :
        i6 == 1 ? vec3(0.0, 1.0, 0.0) :
        i6 == 2 ? vec3(0.0, 0.0, 1.0) :
        i6 == 3 ? vec3(-1.0, 0.0, 0.0) :
        i6 == 4 ? vec3(0.0, 0.0, -1.0) :
                  vec3(0.0, -1.0, 0.0)
      );

      rot -= dir * (start + end);

      vec3 s = abs(dir) * (end - start - 1E-3) + 0.15;
      vec4 isect2 = isectRoundedBox(rot, rd, s, 0.01);

      if (isect2.w < isect.w) {
        isect = isect2;
      }
    }
  }

  isect.xyz = invRotObject(isect.xyz);

  return isect;
}

vec3 sampleGGX(vec2 Xi, vec3 N, float roughnessSq) {
  float phi = Xi.x * TAU;
  float cosTheta = sqrt((1.0 - Xi.y) / (1.0 + (roughnessSq - 1.0) * Xi.y));
  float sinTheta = sqrt(1.0 - cosTheta * cosTheta);

  return orthBas(N) * vec3(
    sinTheta * cos(phi),
    sinTheta * sin(phi),
    cosTheta
  );
}

float fresnelSchlick(float dotVH, float f0, float f90) {
  return mix(
    f0,
    f90,
    pow(max(1.0 - dotVH, 0.0), 5.0)
  );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  seed = uvec3(fragCoord, iFrame);

  vec2 uv = fragCoord / iResolution.xy;
  vec2 p = uv * 2.0 - 1.0;
  p.x *= iResolution.x / iResolution.y;

  vec3 ro = vec3(-0.3, 0.0, 2.2);
  vec3 rd = normalize(vec3(p, -3.0));

  vec3 ro0 = ro;
  vec3 rd0 = rd;

  float isFirstRay = 1.0;

  vec3 N0 = vec3(0.0);
  vec3 col = vec3(0.0);
  vec3 colRem = vec3(1.0);
  float samples = 1.0;

  for (int i = 0; i < TRACE_ITER; i++) {
    vec4 isect = isectObject(ro, rd);

    vec3 N = isect.xyz;
    float isectlen = isect.w;

    if (0.0 < isectlen && isectlen < FAR) {
      ro += rd * isectlen;

      if (isFirstRay == 1.0) {
        ro0 = ro;
        N0 = N;
        isFirstRay = 0.0;
      }

      vec3 h = sampleGGX(random3().xy, N, ROUGHNESS_SQ);
      float dotVH = max(dot(-rd, h), 0.001);

      rd = normalize(reflect(rd, h));

      colRem *= fresnelSchlick(dotVH, 0.5, 1.0);
      colRem *= step(0.0, dot(rd, N));

      ro += EPSILON * rd;
    } else {
      ro *= sign(rd.x);
      rd *= sign(rd.x);

      float plane = isectPlane(ro - vec3(5.0, 0.0, 0.0), rd, vec3(-1.0, 0.0, 0.0));
      vec3 rp = plane * rd + ro;
      float planeLight = LIGHT_AMP * step(plane, FAR - 1E-3) * step(abs(rp.y), 4.0) * step(abs(rp.z), 4.0);

      col += colRem * planeLight;

      colRem *= 0.0;
    }

    if (colRem.x < 0.04) {
      if (isFirstRay == 1.0) {
        break;
      }

      colRem = vec3(1.0);
      samples += 1.0;

      ro = ro0;
      rd = rd0;

      vec3 h = sampleGGX(random3().xy, N0, ROUGHNESS_SQ);
      float dotVH = max(dot(-rd, h), 0.001);

      rd = normalize(reflect(rd, h));

      colRem *= fresnelSchlick(dotVH, 0.5, 1.0);
      colRem *= step(0.0, dot(rd, N0));

      ro += EPSILON * rd;
    }
  }

  if (N0 == vec3(0.0)) {
    fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    return;
  }

  fragColor = vec4(col / samples, 1.0);
}
